import type { Metadata } from "next";

/**
 * SEO helpers: page metadata (title, description, canonical, Open Graph,
 * Twitter) and schema.org structured data for the public website.
 */

/** Name used in page titles, structured data and the default share image */
export const SITE_NAME = "Harsh Bhosale";
export const SITE_TAGLINE = "Stories that deserve a closer look";

/** Generated by app/og/route.tsx */
export const DEFAULT_OG_IMAGE = { url: "/og", width: 1200, height: 630, alt: `${SITE_NAME}: ${SITE_TAGLINE}` };

type PageSeo = {
    /** The page's own part; the layout template adds " | Harsh Bhosale" */
    title: string;
    /** Use the title as-is, without the template (home page) */
    absoluteTitle?: boolean;
    /** Aim for 120–160 characters */
    description: string;
    /** Canonical path, e.g. "/videos" — query strings like ?tab=read point back here */
    path: string;
    /** Share image; the default card when empty */
    image?: string | null;
    article?: { publishedTime?: string | null; modifiedTime?: string | null; tags?: string[] };
};

/**
 * Metadata for one public page. Open Graph and Twitter objects replace the
 * layout's (Next.js merges metadata shallowly), so every page sets them in full.
 */
export function pageMetadata({ title, absoluteTitle, description, path, image, article }: PageSeo): Metadata {
    const fullTitle = absoluteTitle ? title : `${title} | ${SITE_NAME}`;
    const images = image ? [{ url: image, alt: title }] : [DEFAULT_OG_IMAGE];

    const base = { title: fullTitle, description, url: path, siteName: SITE_NAME, locale: "en_IN", images };

    return {
        title: absoluteTitle ? { absolute: title } : title,
        description,
        alternates: { canonical: path },
        openGraph: article
            ? {
                ...base,
                type: "article",
                publishedTime: article.publishedTime ?? undefined,
                modifiedTime: article.modifiedTime ?? undefined,
                authors: [SITE_NAME],
                tags: article.tags,
            }
            : { ...base, type: "website" },
        twitter: { card: "summary_large_image", title: fullTitle, description, images },
    };
}

/* =============================================================
   STRUCTURED DATA (JSON-LD) — rendered with components/common/JsonLd
============================================================= */

type Schema = Record<string, unknown>;

/** Stable ids so pages can reference the site and its author */
export const personId = (origin: string) => `${origin}/#person`;
export const websiteId = (origin: string) => `${origin}/#website`;

export function websiteSchema(origin: string, name: string, description: string): Schema {
    return {
        "@context": "https://schema.org",
        "@type": "WebSite",
        "@id": websiteId(origin),
        url: origin,
        name,
        description,
        inLanguage: ["en", "hi"],
        publisher: { "@id": personId(origin) },
    };
}

export function personSchema(origin: string, sameAs: string[], image?: string | null): Schema {
    return {
        "@context": "https://schema.org",
        "@type": "Person",
        "@id": personId(origin),
        name: SITE_NAME,
        url: origin,
        description: SITE_TAGLINE,
        ...(image && { image }),
        ...(sameAs.length > 0 && { sameAs }),
    };
}

/** Home → … → current page */
export function breadcrumbSchema(origin: string, items: { name: string; path: string }[]): Schema {
    return {
        "@context": "https://schema.org",
        "@type": "BreadcrumbList",
        itemListElement: items.map((item, index) => ({
            "@type": "ListItem",
            position: index + 1,
            name: item.name,
            item: `${origin}${item.path}`,
        })),
    };
}

export function articleSchema(
    origin: string,
    article: {
        path: string;
        headline: string;
        description: string;
        image: string;
        datePublished?: string | null;
        dateModified?: string | null;
        section?: string;
        keywords?: string[];
        type?: "Article" | "NewsArticle";
    }
): Schema {
    return {
        "@context": "https://schema.org",
        "@type": article.type ?? "Article",
        mainEntityOfPage: `${origin}${article.path}`,
        headline: article.headline.slice(0, 110), // Google truncates longer headlines
        description: article.description,
        image: [absolute(origin, article.image)],
        ...(article.datePublished && { datePublished: article.datePublished }),
        ...((article.dateModified ?? article.datePublished) && { dateModified: article.dateModified ?? article.datePublished }),
        ...(article.section && { articleSection: article.section }),
        ...(article.keywords?.length && { keywords: article.keywords.join(", ") }),
        author: { "@id": personId(origin), "@type": "Person", name: SITE_NAME, url: origin },
        publisher: { "@id": personId(origin) },
        isPartOf: { "@id": websiteId(origin) },
    };
}

export function videoSchema(
    origin: string,
    video: {
        id: string;
        name: string;
        description: string;
        thumbnail: string;
        uploadDate: string;
        durationSeconds?: number | null;
        pagePath: string;
    }
): Schema {
    return {
        "@context": "https://schema.org",
        "@type": "VideoObject",
        name: video.name,
        description: video.description || video.name,
        thumbnailUrl: [absolute(origin, video.thumbnail)],
        uploadDate: video.uploadDate,
        ...(video.durationSeconds && { duration: isoDuration(video.durationSeconds) }),
        embedUrl: `https://www.youtube.com/embed/${video.id}`,
        contentUrl: `https://www.youtube.com/watch?v=${video.id}`,
        url: `${origin}${video.pagePath}`,
        author: { "@id": personId(origin), "@type": "Person", name: SITE_NAME },
    };
}

/** 3723 → "PT1H2M3S" */
export function isoDuration(seconds: number) {
    const h = Math.floor(seconds / 3600);
    const m = Math.floor((seconds % 3600) / 60);
    const s = seconds % 60;
    return `PT${h ? `${h}H` : ""}${m ? `${m}M` : ""}${s || (!h && !m) ? `${s}S` : ""}`;
}

/** Search-result length description: whitespace collapsed, cut at a word */
export function metaDescription(text: string, length = 160) {
    const flat = text.replace(/\s+/g, " ").trim();
    if (flat.length <= length) return flat;
    const cut = flat.slice(0, length - 1);
    return `${cut.slice(0, cut.lastIndexOf(" ") > 0 ? cut.lastIndexOf(" ") : cut.length)}…`;
}

const absolute = (origin: string, url: string) => (url.startsWith("http") ? url : `${origin}${url}`);
